const { chromium } = require('C:\\\\Users\\\\gosts\\\\AppData\\\\Roaming\\\\npm\\\\node_modules\\\\playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const context=await browser.newContext({viewport:{width:1365,height:900}});
 await context.route('**/*', async route=>{ const u=new URL(route.request().url()); if(u.hostname==='localhost') await route.continue(); else await route.abort(); });
 const ids=['CH05-L01-S01','CH05-L01-S02','CH05-L01-S03','CH05-L01-S04','CH05-L01-S05','CH05-L01-S06','CH05-L01-S07','CH05-L02-S01','CH05-L02-S02','CH05-L03-S01','CH05-L04-S01','CH05-L04-S02','CH05-L05-S01','CH05-L05-S02'];
 const out=[];
 for(const id of ids){
  const p=await context.newPage(); const errs=[]; p.on('pageerror',e=>errs.push('page:'+e.message)); p.on('console',m=>{if(m.type()==='error') errs.push('console:'+m.text())});
  let rec={id};
  try{
   const resp=await p.goto('http://localhost:8141/embeds/abap/'+id+'.html',{waitUntil:'networkidle',timeout:15000});
   rec.status=resp&&resp.status();
   rec.dim=await p.evaluate(()=>({sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,sh:document.documentElement.scrollHeight,buttons:[...document.querySelectorAll('button')].map(b=>b.textContent.trim()),details:document.querySelectorAll('details').length,text:document.body.innerText.slice(0,180)}));
   const start=p.locator('[data-start]'); if(await start.count()){await start.click(); const next=p.locator('[data-next]'); let n=0; while(n<80 && await next.isEnabled()){await next.click(); n++;} rec.steps=n; rec.counter=await p.locator('[data-counter]').textContent(); rec.console=(await p.locator('[data-console]').textContent()).slice(-180);}
   const details=p.locator('details > summary'); if(await details.count()){for(let i=0;i<await details.count();i++) await details.nth(i).click(); rec.openDetails=await p.locator('details[open]').count();}
   const generic=p.locator('button:not([data-start]):not([data-next])'); rec.genericButtons=await generic.count(); for(let i=0;i<Math.min(await generic.count(),12);i++){try{await generic.nth(i).click({timeout:1000});}catch{}}
   rec.errors=errs;
  }catch(e){rec.fail=e.message; rec.errors=errs;}
  out.push(rec); await p.close();
 }
 await browser.close(); console.log(JSON.stringify(out,null,2));
})();
'@ | node -"

